import{_ as t,o as a,c as s,ag as n}from"./chunks/framework.44aEvdQQ.js";const u=JSON.parse('{"title":"Financials & P&L","description":"","frontmatter":{},"headers":[],"relativePath":"reference/concepts/financials.md","filePath":"reference/concepts/financials.md"}'),r={name:"reference/concepts/financials.md"};function o(i,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="financials-p-l" tabindex="-1">Financials &amp; P&amp;L <a class="header-anchor" href="#financials-p-l" aria-label="Permalink to &quot;Financials &amp; P&amp;L&quot;">​</a></h1><p>VERA calculates revenue, cost, and margin live from time entries, rate history, and project metadata. No manual spreadsheet formulas needed on the operational side — the data flows automatically to the reporting sheet.</p><hr><h2 id="revenue-by-project-type" tabindex="-1">Revenue by project type <a class="header-anchor" href="#revenue-by-project-type" aria-label="Permalink to &quot;Revenue by project type {#revenue-by-project-type}&quot;">​</a></h2><p>Revenue recognition depends on the project type.</p><h3 id="pro-bono" tabindex="-1">Pro Bono <a class="header-anchor" href="#pro-bono" aria-label="Permalink to &quot;Pro Bono&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Revenue = $0</span></span></code></pre></div><p>Always. Hours are tracked for cost purposes only.</p><h3 id="t-m-time-materials" tabindex="-1">T&amp;M (Time &amp; Materials) <a class="header-anchor" href="#t-m-time-materials" aria-label="Permalink to &quot;T&amp;M (Time &amp; Materials)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Revenue = hours_logged × billing_rate</span></span></code></pre></div><p>Accrues per entry. Work should stop when <code>hours_budget</code> is exhausted — logging beyond that point earns no additional revenue and runs at pure cost.</p><h3 id="fixed-price" tabindex="-1">Fixed Price <a class="header-anchor" href="#fixed-price" aria-label="Permalink to &quot;Fixed Price&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Revenue = (hours_logged ÷ hours_budget) × contract_value</span></span>
<span class="line"><span>         capped at contract_value (100%)</span></span></code></pre></div><p>Revenue accrues as a percentage of completion. Logging 50% of the budgeted hours recognises 50% of the contract value. When the hours budget is used up, 100% of the contract value has been recognised.</p><h3 id="retainer" tabindex="-1">Retainer <a class="header-anchor" href="#retainer" aria-label="Permalink to &quot;Retainer&quot;">​</a></h3><p>Revenue is the fixed monthly retainer fee — this is not calculated per-entry. Instead, VERA tracks <strong>burn rate</strong>: whether the agency is delivering the contracted hours and therefore earning the fee. See <a href="/vera-docs/reference/concepts/retainers.html">Retainers</a>.</p><h3 id="agile-sprint-based" tabindex="-1">Agile (Sprint-based) <a class="header-anchor" href="#agile-sprint-based" aria-label="Permalink to &quot;Agile (Sprint-based)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Revenue per sprint = (hours_logged ÷ hours_budget) × contract_value</span></span>
<span class="line"><span>                     capped at contract_value</span></span>
<span class="line"><span>                     when sprint status = &#39;active&#39;</span></span></code></pre></div><p>Sprints with <code>status = &#39;planned&#39;</code> recognise $0 — work has not started. Once activated, revenue accrues the same way as Fixed Price but per-sprint.</p><hr><h2 id="cost-calculation" tabindex="-1">Cost calculation <a class="header-anchor" href="#cost-calculation" aria-label="Permalink to &quot;Cost calculation {#cost-calculation}&quot;">​</a></h2><p>Cost = what the agency pays to deliver the work.</p><p><strong>Standard calculation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cost = hours_logged × hourly_cost</span></span></code></pre></div><p>Where <code>hourly_cost</code> is the rate effective on the entry&#39;s date, looked up from Rate History.</p><p><strong>Vendor with liability:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cost = liability.agreed_amount  (overrides hours × rate entirely)</span></span></code></pre></div><p>If a liability exists for vendor X on project Y, the liability&#39;s <code>agreed_amount</code> becomes the cost for that vendor on that project — regardless of how many hours are logged. The two methods are never mixed for the same vendor/project pair.</p><h3 id="rate-history-lookup" tabindex="-1">Rate History lookup <a class="header-anchor" href="#rate-history-lookup" aria-label="Permalink to &quot;Rate History lookup&quot;">​</a></h3><p>Rate History is append-only and effective-date versioned. When calculating cost for an entry dated 2026-01-15:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Look up 13. Rate History WHERE user_id = X</span></span>
<span class="line"><span>Find MAX(effective_from) WHERE effective_from ≤ 2026-01-15</span></span>
<span class="line"><span>Use that row&#39;s hourly_cost</span></span></code></pre></div><p>This means a salary increase on 2026-03-01 affects costs from that date forward, but leaves all historical entries unchanged.</p><hr><h2 id="margin" tabindex="-1">Margin <a class="header-anchor" href="#margin" aria-label="Permalink to &quot;Margin&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Margin = Revenue − Cost</span></span>
<span class="line"><span>Margin % = Margin ÷ Revenue × 100</span></span></code></pre></div><p>Shown as:</p><ul><li><strong>Dollar amount</strong> to Owners</li><li><strong>Percentage only</strong> to Managers</li></ul><hr><h2 id="the-billing-rate-vs-hourly-cost-distinction" tabindex="-1">The billing_rate vs. hourly_cost distinction <a class="header-anchor" href="#the-billing-rate-vs-hourly-cost-distinction" aria-label="Permalink to &quot;The billing_rate vs. hourly_cost distinction&quot;">​</a></h2><p>These are two different rates that are easy to confuse:</p><table tabindex="0"><thead><tr><th></th><th><code>billing_rate</code></th><th><code>hourly_cost</code></th></tr></thead><tbody><tr><td><strong>What it is</strong></td><td>What you charge the client</td><td>What the agency pays the team member</td></tr><tr><td><strong>Used for</strong></td><td>Revenue calculation</td><td>Cost calculation</td></tr><tr><td><strong>Where</strong></td><td><code>22. Projects Master</code></td><td><code>13. Rate History</code></td></tr><tr><td><strong>Who sees it</strong></td><td>Owner</td><td>Owner only</td></tr><tr><td><strong>Typical values</strong></td><td>$125–$200/hr</td><td>$50–$120/hr</td></tr></tbody></table><p>The gap between them is the gross margin per hour.</p><hr><h2 id="financial-access-by-role" tabindex="-1">Financial access by role <a class="header-anchor" href="#financial-access-by-role" aria-label="Permalink to &quot;Financial access by role&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Owner</th><th>Manager</th><th>User</th></tr></thead><tbody><tr><td>Revenue ($)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Cost ($)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Margin ($)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Contract value</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Billing rate</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Hourly cost (rates)</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Budget % used</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>Hours logged</td><td>✅</td><td>✅ (assigned projects)</td><td>✅ (own only)</td></tr></tbody></table><p>Managers see percentages, not dollars. Users see their own hours only.</p><hr><h2 id="monthly-report" tabindex="-1">Monthly report <a class="header-anchor" href="#monthly-report" aria-label="Permalink to &quot;Monthly report&quot;">​</a></h2><p><code>generate_monthly_report</code> produces a portfolio view for the current (or specified) month:</p><ul><li>Per-project: hours logged, budget hours, utilisation %, burn status</li><li>Revenue at risk: projects over budget</li><li>Open unresolved items count</li><li>Summary: over budget count, under-utilised count</li></ul><p>Available to Owners (with dollar amounts) and Managers (with percentages, own projects only).</p><hr><h2 id="variance" tabindex="-1">Variance <a class="header-anchor" href="#variance" aria-label="Permalink to &quot;Variance&quot;">​</a></h2><p>Variance appears in two contexts:</p><p><strong>Hour variance</strong> (from <code>22. Projects Master</code> formula columns):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hour_variance = estimated_hours − actual_hours</span></span></code></pre></div><p>Positive = under budget. Negative = over budget.</p><p><strong>Cost variance</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cost_variance = estimated_cost − actual_labor_cost</span></span></code></pre></div><p><strong>Variance %</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>variance_pct = cost_variance ÷ contract_value</span></span></code></pre></div><p>These formula columns (I–O in Projects Master) are user-maintained — VERA writes the source data (cols A–H) but the variance calculations are Google Sheets formulas set up in the reporting sheet.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="/vera-docs/blog/06-roles-and-dollars.html">The Data Is Only Worth Protecting If It&#39;s Worth Something</a> — why financial visibility is role-gated, and what each role actually needs to see</li></ul>`,64)])])}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
